head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.toDay = '';
scwin.clientnow = new Date();

/* 오늘 날짜를 구한다 */
scwin.curYear = scwin.clientnow.getYear();
scwin.curMonth = (scwin.clientnow.getMonth()) + 1;
scwin.curDay = scwin.clientnow.getDate();
if (scwin.curMonth <= 9) {
    scwin.curMonth = "0" + scwin.curMonth;
}
if (scwin.curDay <= 9) {
    scwin.curDay = "0" + scwin.curDay;
}
scwin.toDay = scwin.curYear + "" + scwin.curMonth + "" + scwin.curDay;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_dSetLst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dSetLst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dSetCnt",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dSetCnt=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        $c.cm.PanelToGroupBox_01(panel_1);
        // PanelToGroupBox_02(panel_2);
        await scwin.setToDate();
        await scwin.listSyncAuto();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dSetLst_OnLoadCompleted
 * @description dSetLst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dSetLst_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80500.dSetLst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description btn_cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_cal_onclick = function() {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80500.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sys_search_onclick = async function() {
    try {
        if (txb_date.getValue() !== "") {
            await scwin.listSync();
            await scwin.cntSync();
        } else {
            await $c.win.alert("일자를 지정하십시요");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80500.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name txb_date_OnDblClick
 * @description txb_date 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_date_OnDblClick = async function() {
    try {
        if (txb_date.getValue() !== "") {
            await scwin.listSync();
            await scwin.cntSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80500.txb_date_OnDblClick" });
    }
};

/**
 * @method
 * @name tbMktG_onchange
 * @description tbMktG 변경 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tbMktG_onchange = async function() {
    try {
        await scwin.chkCntVal(tbMktG);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80500.tbMktG_onchange" });
    }
};

/**
 * @method
 * @name dSetCnt_OnLoadCompleted
 * @description dSetCnt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dSetCnt_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name btn_toExcel_onmouseover
 * @description 「엑셀다운로드」 onmouseover 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toExcel_onmouseover = function() {
    try {
        btn_toExcel.setBackgroundImage("../img/2_butt_toexcel.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80500.btn_toExcel_onmouseover" });
    }
};

/**
 * @method
 * @name btn_toExcel_onmouseout
 * @description 「엑셀다운로드」 onmouseout 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toExcel_onmouseout = function() {
    try {
        btn_toExcel.setBackgroundImage("../img/2_butt_toexcel_dis.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80500.btn_toExcel_onmouseout" });
    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toExcel_onclick = function() {
    try {
        if (dSetLst.getRowCount() !== 0) $c.data.downloadGridViewExcel(mgLst, {fileName: "일별투자참고", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80500.btn_toExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dSetLst",
        action : "/byddinvst.do",
        ref : "",
        target : "dSetLst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name cntSync
 * @description cnt Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cntSync = async function() {
    const sbmOptions = {
        id : "sbm_dSetCnt",
        action : "/byddinvst.do",
        ref : "",
        target : "dSetCnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSyncAuto
 * @description list Sync Auto 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSyncAuto = async function() {
    setInterval('fn_list_sync()', 30000);
    await scwin.listSync();
};

/**
 * @method
 * @name chkCntVal
 * @description chk Cnt Val 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkCntVal = async function(obj) {
    await $c.win.alert(obj.getValue());
    const ver = obj.getValue();
    if (ver !== '120') obj.setValue(obj.getValue() + ' 이상');
};

/**
 * @method
 * @name setToDate
 * @description set To Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setToDate = async function() {
    txb_date.setValue(scwin.toDay);
    await scwin.listSync();
    await scwin.cntSync();
};
